def AdmitsHilbertianGrading [UniformSpace X] : Prop :=
  ∃ p : ℕ → RightSeminorm X, Monotone (fun k => (p k).toRealSeminorm) ∧
    WithSeminorms (fun k => (p k).toRealSeminorm) ∧ ∀ k, SeminormIsHilbertian (p k)

